V C_PetrifiedTorchTests::m_zombie_deck(const Args& A) {
    V L_extra = (A.size() > 0 || A.has_kw(SY("extra"))) ? A.get(0, SY("extra"), nullptr) : V(V::tuple({}));
    return (V::list({SV("zombie:脑光墓碑"), pm_test_pvp_petrified_torch::GRAVE, SV("zombie:普通僵尸")}) + py::list_it(L_extra));
    return V::none();
}

V C_PetrifiedTorchTests::m_grave_at(const Args& A) {
    V L_b = A.get(0, SY("b"), nullptr, "grave_at");
    V L_col = A.get(1, SY("col"), nullptr, "grave_at");
    V L_row = (A.size() > 2 || A.has_kw(SY("row"))) ? A.get(2, SY("row"), nullptr) : V(pm_test_pvp_petrified_torch::GRAVE_ROW);
    V L_unit;
    L_unit = callm(L_b, SY("spawn"), Args{pm_test_pvp_petrified_torch::GRAVE, SV("zombie"), ((L_col + V(0.5)) * pvz::getattr(L_b, SY("tile"))), ((L_row + V(1.0)) * pvz::getattr(L_b, SY("tile")))});
    (void)(m_assertIsNotNone(Args{L_unit, SV("the grave card must create a native record")}));
    return L_unit;
    return V::none();
}

V C_PetrifiedTorchTests::m_watch_peas(const Args& A) {
    V L_frames = A.get(0, SY("frames"), nullptr, "watch_peas");
    V L_shooter = A.get(1, SY("shooter"), nullptr, "watch_peas");
    V L_gun_col = A.get(2, SY("gun_col"), nullptr, "watch_peas");
    V L_grave_col = (A.size() > 3 || A.has_kw(SY("grave_col"))) ? A.get(3, SY("grave_col"), nullptr) : V(pm_test_pvp_petrified_torch::GRAVE_COL);
    V L_target_x = (A.size() > 4 || A.has_kw(SY("target_x"))) ? A.get(4, SY("target_x"), nullptr) : V(V(1104.0));
    V L__;
    V L_b;
    V L_e;
    V L_flips;
    V L_grave;
    V L_key;
    V L_name;
    V L_order;
    V L_seen;
    V L_z;
    V L_zrecord;
    L_b = m_battle(Args({}, {{SY("plants"), V::list({(SV("plant:") + L_shooter), SV("plant:花盆")})}, {SY("zombies"), m_zombie_deck(Args{})}}));
    (void)(callm(L_b, SY("spawn"), Args{(SV("plant:") + L_shooter), SV("plant"), ((L_gun_col + V(0.5)) * pvz::getattr(L_b, SY("tile"))), V(480.0)}));
    L_grave = m_grave_at(Args{L_b, L_grave_col});
    L_z = callm(L_b, SY("spawn"), Args{SV("zombie:普通僵尸"), SV("zombie"), L_target_x, V(480.0)});
    setm(rd(pvz::getattr(L_b, SY("_native_objects")), rd(L_z, SV("id"))), &Obj::血量, SV("血量"), V(10000000.0));
    L_zrecord = py::next([&]() -> V { V out_ = V::list(); V L_o; { V it1_ = py::iter_list(rdm(pvz::getattr(L_b, SY("g")), &Obj::僵尸, SV("僵尸"))); for (size_t i1_ = 0; i1_ < it1_.len(); ++i1_) { L_o = it1_.idx(int64_t(i1_)); if (!((py::m_get_slot(L_o, &Obj::_pvp_id, SV("_pvp_id")) == rd(L_z, SV("id"))))) continue; out_.append(L_o); }}return out_; }());
    { V tv2_0 = py_dict({}); V tv2_1 = V::list({}); V tv2_2 = py_dict({}); L_seen = std::move(tv2_0); L_order = std::move(tv2_1); L_flips = std::move(tv2_2); }
    { const int64_t b3_ = 0, e3_ = (int64_t)(L_frames).num(), s3_ = 1;
    for (int64_t i3_ = b3_; s3_ > 0 ? i3_ < e3_ : i3_ > e3_; i3_ += s3_) {
        L__ = V(double(i3_)); 
        pvz::setitem(rdm(L_zrecord, &Obj::位置, SV("位置")), V(0.0), L_target_x);
        (void)(callm(L_b, SY("_step_original"), Args({}, {{SY("draw"), V(false)}})));
        { V it4_ = py::iter_list(rd(pvz::getattr(L_b, SY("g")), SV("实体")));
        for (size_t i4_ = 0; i4_ < it4_.len(); ++i4_) {
            L_e = it4_.idx(int64_t(i4_)); 
            if ((!(V((isinstance(L_e, "dict")))).truthy() || (py::m_get_slot(L_e, &Obj::僵尸豌豆弹, SV("僵尸豌豆弹"))).truthy())) {
                continue;
            }
            if (!py::in(py::m_get_slot(L_e, &Obj::名, SV("名")), pm_test_pvp_petrified_torch::PEA_NAMES)) {
                continue;
            }
            L_key = py_or(py::m_get_slot(L_e, &Obj::_pvp_id, SV("_pvp_id")), [&]() -> V { return py::id(L_e); });
            L_name = rdm(L_e, &Obj::名, SV("名"));
            if (!py::in(L_key, L_seen)) {
                pvz::setitem(L_seen, L_key, L_name);
                (void)(py::m_append(L_order, L_key));
                pvz::setitem(L_flips, L_key, V::list({}));
            } else if ((rd(L_seen, L_key) != L_name)) {
                pvz::setitem(L_seen, L_key, L_name);
                (void)(py::m_append(rd(L_flips, L_key), py::round(rd(rdm(L_e, &Obj::位置, SV("位置")), V(0.0)), V(1.0))));
            }
        }}
    }}
    return V::tuple({L_b, L_grave, L_seen, L_order, L_flips});
    return V::none();
}

V C_PetrifiedTorchTests::m_test_card_face_values(const Args& A) {
    V L_card;
    L_card = rd(pm_catalog::CARDS, pm_test_pvp_petrified_torch::GRAVE);
    // PvP73 balance (user request 11-11): 石化火炬 deploy cooldown 48 s (was 20 s).
    (void)(m_assertEqual(Args{V::tuple({V(200.0), V(48.0), V(800.0)}), V::tuple({rd(L_card, SV("cost")), rd(L_card, SV("cooldown")), rd(L_card, SV("hp"))})}));
    (void)(m_assertFalse(Args{rd(L_card, SV("producer")), SV("石化火炬 must not produce")}));
    (void)(m_assertEqual(Args{SV("grave"), rd(L_card, SV("behavior"))}));
    (void)(m_assertEqual(Args{SV("economy"), rd(L_card, SV("category"))}));
    (void)(m_assertTrue(Args{rd(L_card, SV("selectable"))}));
    (void)(m_assertEqual(Args{SV("zombie"), rd(L_card, SV("side"))}));
    return V::none();
}

V C_PetrifiedTorchTests::m_test_it_follows_the_economy_native_column_rule(const Args& A) {
    V L_actual;
    V L_actual_card;
    V L_card;
    L_actual_card = V::func(pm_catalog::f_actual_card);
    L_card = rd(pm_catalog::CARDS, pm_test_pvp_petrified_torch::GRAVE);
    (void)(m_assertIsNone(Args{rd(L_card, SV("native_hp"))}));
    (void)(m_assertIsNone(Args{rd(L_card, SV("native_cost"))}));
    (void)(m_assertEqual(Args{V(800.0), rd(L_card, SV("hp"))}));
    L_actual = (L_actual_card).call(Args{pm_test_pvp_petrified_torch::GRAVE});
    (void)(m_assertEqual(Args{V(800.0), rd(L_actual, SV("hp"))}));
    (void)(m_assertEqual(Args{V(48.0), rd(L_actual, SV("cooldown"))}));  // PvP73: 48 s (was 20 s)
    (void)(m_assertEqual(Args{V(200.0), rd(L_actual, SV("cost"))}));
    return V::none();
}

V C_PetrifiedTorchTests::m_test_it_is_bannable_and_never_satisfies_the_starter_grave_rule(const Args& A) {
    (void)(m_assertTrue(Args{pm_catalog::f_allowed(Args{pm_test_pvp_petrified_torch::GRAVE}), SV("an ordinary gravestone is bannable")}));
    (void)(m_assertFalse(Args{pm_catalog::f_allowed(Args({pm_test_pvp_petrified_torch::GRAVE}, {{SY("bans"), V::tuple({pm_test_pvp_petrified_torch::GRAVE})}}))}));
    (void)(m_assertFalse(Args{pm_catalog::f_starter_grave(Args{pm_test_pvp_petrified_torch::GRAVE}), SV("a non-producer grave cannot be the affordable starter")}));
    (void)(m_assertEqual(Args{SV("必须保留一种开局可负担的经济墓碑"), pm_catalog::f_validate_deck(Args({SV("zombie"), V::list({pm_test_pvp_petrified_torch::GRAVE})}, {{SY("slots"), V(7.0)}}))}));
    return V::none();
}

V C_PetrifiedTorchTests::m_test_the_grave_is_a_native_record_with_800_life_it_can_spawn_from(const Args& A) {
    V L_b;
    V L_grave;
    V L_native;
    V L_soldier;
    L_b = m_battle(Args({}, {{SY("zombies"), m_zombie_deck(Args{})}}));
    L_grave = m_grave_at(Args{L_b, pm_test_pvp_petrified_torch::GRAVE_COL});
    L_native = rd(pvz::getattr(L_b, SY("_native_objects")), rd(L_grave, SV("id")));
    (void)(m_assertTrue(Args{py::m_get_slot(L_native, &Obj::_pvp_grave, SV("_pvp_grave"))}));
    (void)(m_assertEqual(Args{V(800.0), rdm(L_native, &Obj::血量, SV("血量"))}));
    (void)(m_assertEqual(Args{V(800.0), rdm(L_native, &Obj::_pvp_max_hp, SV("_pvp_max_hp"))}));
    (void)(m_assertEqual(Args{V::tuple({V(600.0), V(480.0)}), rdm(L_native, &Obj::_pvp_anchor, SV("_pvp_anchor"))}));
    (void)(callm(L_b, SY("step"), Args{V(2.0)}));
    L_soldier = m_deploy(Args({L_b, SV("zombie"), SV("zombie:普通僵尸"), pm_test_pvp_petrified_torch::GRAVE_COL}, {{SY("grave"), rd(L_grave, SV("id"))}}));
    (void)(m_assertIsNotNone(Args{L_soldier, SV("a zombie must be deployable from this grave")}));
    (void)(m_assertEqual(Args{SV("zombie"), rd(rd(pvz::getattr(L_b, SY("units")), rdm(L_soldier, &Obj::_pvp_id, SV("_pvp_id"))), SV("side"))}));
    return V::none();
}

