    L_names_of = V::func([=, this](const Args& A) mutable -> V {
    V L_frames = A.get(0, SY("frames"), nullptr, "names_of");
    V L_seen = A.get(1, SY("seen"), nullptr, "names_of");
    V L__;
    V L_e;
    V L_key;
    V L_out;
    L_out = py_dict({});
    { const int64_t b1_ = 0, e1_ = (int64_t)(L_frames).num(), s1_ = 1;
    for (int64_t i1_ = b1_; s1_ > 0 ? i1_ < e1_ : i1_ > e1_; i1_ += s1_) {
        L__ = V(double(i1_)); 
        pvz::setitem(rdm(L_zrecord, &Obj::位置, SV("位置")), V(0.0), V(1104.0));
        (void)(callm(L_b, SY("_step_original"), Args({}, {{SY("draw"), V(false)}})));
        { V it2_ = py::iter_list(rd(pvz::getattr(L_b, SY("g")), SV("实体")));
        for (size_t i2_ = 0; i2_ < it2_.len(); ++i2_) {
            L_e = it2_.idx(int64_t(i2_)); 
            if ((!(V((isinstance(L_e, "dict")))).truthy() || (py::m_get_slot(L_e, &Obj::僵尸豌豆弹, SV("僵尸豌豆弹"))).truthy())) {
                continue;
            }
            if (!py::in(py::m_get_slot(L_e, &Obj::名, SV("名")), pm_test_pvp_petrified_torch::PEA_NAMES)) {
                continue;
            }
            L_key = py_or(py::m_get_slot(L_e, &Obj::_pvp_id, SV("_pvp_id")), [&]() -> V { return py::id(L_e); });
            if (!py::in(L_key, L_seen)) {
                pvz::setitem(L_out, L_key, rdm(L_e, &Obj::名, SV("名")));
            }
        }}
    }}
    return L_out;
    return V::none();
});
    L_alive = (L_names_of).call(Args{V(600.0), py::set_it()});
